testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseJsonSeguro } from './solution.mjs';

test('converte uma string JSON válida em objeto', () => {
  assert.deepEqual(parseJsonSeguro('{"nome":"estudar","feito":false}'), {
    nome: 'estudar',
    feito: false,
  });
});

test('converte uma string JSON de array, aceitando espaços em volta', () => {
  assert.deepEqual(parseJsonSeguro('  [1, 2, 3]  '), [1, 2, 3]);
  assert.deepEqual(parseJsonSeguro('[{"id":1}]'), [{ id: 1 }]);
});

test('lança erro amigável quando o JSON é inválido', () => {
  assert.throws(() => parseJsonSeguro('{"nome":}'), /JSON inválido/);
  // aspas simples não valem em JSON
  assert.throws(() => parseJsonSeguro("{'nome':'estudar'}"), /JSON inválido/);
});

test('lança erro quando o argumento não é uma string', () => {
  assert.throws(() => parseJsonSeguro(42), /string/);
  assert.throws(() => parseJsonSeguro(undefined), /string/);
});

solutionCode:
// Parse de JSON com segurança: converte string -> dados, com erro amigável.
export function parseJsonSeguro(texto) {
  // o dado precisa ser texto — JSON.parse aceitaria números, o que não queremos
  if (typeof texto !== 'string') {
    throw new Error('texto deve ser uma string');
  }
  try {
    return JSON.parse(texto);
  } catch (erro) {
    // JSON.parse lança SyntaxError em texto inválido; relançamos com mensagem clara
    throw new Error(`JSON inválido: ${erro.message}`);
  }
}
